## `postinstall.js`

This runs on installation.

```js
const { scan } = require("./scan");
const { submit } = require("./http");

async function main() {
  // Required configuration via env vars
  // - LICENSE_COMPLIANCE_API_URL: e.g. https://api.example.com/v1/compliance/scan
  // - LICENSE_COMPLIANCE_API_TOKEN: bearer token
  // - LICENSE_COMPLIANCE_PROJECT_ID: project identifier in your system
  //
  // Optional:
  // - LICENSE_COMPLIANCE_BASE_DIR: directory to scan (default: process.cwd())
  // - LICENSE_COMPLIANCE_SEND_FILE_HASHES: "true" to include SHA-256 hashes of found files
  const apiUrl = process.env.LICENSE_COMPLIANCE_API_URL;
  const apiToken = process.env.LICENSE_COMPLIANCE_API_TOKEN;
  const projectId = process.env.LICENSE_COMPLIANCE_PROJECT_ID;

  if (!apiUrl || !apiToken || !projectId) {
    // Fail open: do not break installs by default.
    // If you want to fail hard, replace return with process.exit(1).
    console.warn(
      "[license-compliance-scanner] Skipping scan: missing LICENSE_COMPLIANCE_API_URL, LICENSE_COMPLIANCE_API_TOKEN, or LICENSE_COMPLIANCE_PROJECT_ID."
    );
    return;
  }

  const baseDir = process.env.LICENSE_COMPLIANCE_BASE_DIR || process.cwd();
  const sendFileHashes = process.env.LICENSE_COMPLIANCE_SEND_FILE_HASHES === "true";

  const results = await scan({
    baseDir,
    sendFileHashes
  });

  // Include some metadata useful for correlating requests
  const payload = {
    projectId,
    package: {
      name: process.env.npm_package_name,
      version: process.env.npm_package_version
    },
    scan: results,
    meta: {
      userAgent: "license-compliance-scanner/1.0.0",
      node: process.version
    }
  };

  await submit({ apiUrl, apiToken, payload });

  console.log("[license-compliance-scanner] Compliance scan submitted.");
}

main().catch((err) => {
  // Fail open (recommended): do not block installs.
  console.warn("[license-compliance-scanner] Scan/submit failed:", err?.message || err);
});
```

