async function walkDir(rootDir, opts) {
  const {
    ignoreMatchers,
    maxFiles,
    followSymlinks
  } = opts;

  const found = [];
  let fileCount = 0;

  async function walk(currentDir) {
    let entries;
    try {
      entries = await fs.promises.readdir(currentDir, { withFileTypes: true });
    } catch (e) {
      return;
    }

    for (const ent of entries) {
      const full = path.join(currentDir, ent.name);
      const rel = path.relative(rootDir, full);

      // Normalize for minimatch
      const relUnix = rel.split(path.sep).join("/");

      // ignore patterns match relative paths
      if (ignoreMatchers.some((m) => m.match(relUnix))) {
        continue;
      }

      if (ent.isDirectory()) {
        if (ent.isSymbolicLink() && !followSymlinks) continue;
        await walk(full);
        continue;
      }

      if (!ent.isFile()) continue;

      fileCount++;
      if (fileCount > maxFiles) {
        throw new Error(`Max file limit exceeded (${maxFiles}). Aborting scan.`);
      }

      found.push({ fullPath: full, relPath: relUnix });
    }
  }

  await walk(rootDir);
  return found;
