## `main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {}

# VPC (simple default-ish VPC build for demonstration)
resource "aws_vpc" "vpc" {
  cidr_block           = "10.50.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = { Name = "${var.name_prefix}-vpc" }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id
  tags   = { Name = "${var.name_prefix}-igw" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = { Name = "${var.name_prefix}-public-rt" }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.50.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true
  tags = { Name = "${var.name_prefix}-public-a" }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

# Security group to make DB public (also intentionally insecure)
resource "aws_security_group" "db_sg" {
  name        = "${var.name_prefix}-db-sg"
  description = "Intentionally permissive SG for demonstration"
  vpc_id      = aws_vpc.vpc.id

  # ❌ Overly permissive ingress (example): allows all IPs to reach DB port
  ingress {
    description = "INSECURE: allow all IPs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ip_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${var.name_prefix}-db-sg" }
}

# ----------------------------
# 1) Intentionally public S3
# ----------------------------
resource "aws_s3_bucket" "public_bucket" {
  # bucket names must be globally unique
  bucket = "${var.name_prefix}-${data.aws_caller_identity.current.account_id}-public-demo"

  tags = { Name = "${var.name_prefix}-public-bucket" }

  # ❌ Disables the account-level/bucket-level block behavior that prevents public access
  # In modern AWS, this is controlled by aws_s3_bucket_public_access_block,
  # so we also set that resource below.
}

# ❌ Explicitly configure public access block to allow public ACL/policies.
resource "aws_s3_bucket_public_access_block" "public_bucket_block" {
  bucket = aws_s3_bucket.public_bucket.id

  # These four toggles are intentionally set to "false" to allow public exposure.
  block_public_acls       = false
  ignore_public_acls      = false
  block_public_policy     = false
  restrict_public_buckets = false
}

# Put an object so bucket policy can demonstrate access.
resource "aws_s3_object" "demo_object" {
  bucket       = aws_s3_bucket.public_bucket.id
  key          = "hello.txt"
  content      = "INSECURE DEMO: This object is intended to be publicly readable."
  content_type = "text/plain"
}

# ❌ Public bucket policy allowing GetObject to everyone
resource "aws_s3_bucket_policy" "public_read" {
  bucket = aws_s3_bucket.public_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = ["s3:GetObject"]
        Resource  = "${aws_s3_bucket.public_bucket.arn}/*"
      }
    ]
  })
}

# -------------------------------------------
# 2) Intentionally over-permissive IAM policy
# -------------------------------------------
resource "aws_iam_role" "insecure_role" {
  name = "${var.name_prefix}-insecure-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach a policy with wildcards over actions and resources
resource "aws_iam_policy" "overly_permissive" {
  name = "${var.name_prefix}-overly-permissive"

  # ❌ Common misconfiguration: Action: "*" and Resource: "*"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "OverlyBroadAdminLike"
        Effect = "Allow"
        Action = "*"
        Resource = "*"
      },
      {
        Sid    = "InsecureS3Access"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject",
          "s3:*"
        ]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_insecure" {
  role       = aws_iam_role.insecure_role.name
  policy_arn = aws_iam_policy.overly_permissive.arn
}

# -------------------------------------------
# 3) Intentionally unencrypted database (RDS)
# -------------------------------------------
# Note: RDS DB subnet group for "private-ish" but with single public subnet here.
resource "aws_db_subnet_group" "db_subnets" {
  name       = "${var.name_prefix}-db-subnets"
  subnet_ids = [aws_subnet.public_a.id]
  tags = { Name = "${var.name_prefix}-db-subnets" }
}

resource "aws_db_instance" "insecure_db" {
  identifier = "${var.name_prefix}-db"

  engine         = var.engine
  instance_class = var.db_instance_class

  allocated_storage = var.db_allocated_storage

  username = var.db_username
  password = var.db_password

  # Basic settings for lab use
  publicly_accessible = true

  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name   = aws_db_subnet_group.db_subnets.name

  # ❌ Misconfiguration: disable encryption
  storage_encrypted = false

  # Also demonstrate lack of TLS enforcement (depends on engine settings).
  # For Postgres, you'd need parameter group/require SSL;
  # kept minimal here to focus on "storage_encrypted = false".

  skip_final_snapshot = true

  tags = { Name = "${var.name_prefix}-insecure-db" }
}
