# TARGET ACCOUNT (Destination) Terraform

## `target-account/variables.tf`
```hcl
variable "dr_bucket_name_prefix" {
  description = "Prefix for replicated bucket names in target account."
  type        = string
  default     = "dr-"
}

variable "replication_kms_alias" {
  type    = string
  default = "dr-s3-replication"
}
```

## `target-account/main.tf`
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

# ----------------------------
# KMS key for encrypting replicated S3 objects (optional but recommended)
# ----------------------------
resource "aws_kms_key" "dr_s3" {
  description             = "KMS key for DR S3 replication target objects"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "dr_s3" {
  name          = "alias/${var.replication_kms_alias}"
  target_key_id = aws_kms_key.dr_s3.id
}

# ----------------------------
# IAM role used by SOURCE-account replication (S3 CRR)
# Source needs to assume a role in target account.
# We'll create trust; policy should allow writing to replicated buckets.
# ----------------------------
variable "source_account_id" {
  type = string
}

resource "aws_iam_role" "s3_replication_destination" {
  name = "dr-s3-replication-destination"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.source_account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# This policy allows replication role to replicate objects into destination buckets.
# Because bucket names are dynamic (one per source bucket), we allow access to
# buckets matching a prefix. Adjust as needed.
resource "aws_iam_policy" "s3_replication_destination_policy" {
  name = "dr-s3-replication-destination-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
          "s3:AbortMultipartUpload",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::${var.dr_bucket_name_prefix}*",
          "arn:aws:s3:::${var.dr_bucket_name_prefix}*/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.dr_s3.arn]
      }
    ]
  })
}

